function confirmDeleteLesson(lesson) {
  const copy = online
    ? 'Bài sẽ bị xóa khỏi thư viện của bạn. Audio được giải phóng nếu không còn bài sử dụng.'
    : 'Bài sẽ bị xóa khỏi thư viện. File gốc vẫn ở thư mục data.';
  modal('Xóa bài nghe này?', '<p><b>' + e(lesson.title) + '</b></p><p>' + copy +
    '</p><div class="modal-footer"><button class="btn secondary" data-action="close-modal">Giữ bài</button>' +
    '<button class="btn danger" data-action="confirm-delete">Xóa bài</button></div>');
}

function wholePracticeView(lesson) {
  const progress = state.progress[lesson.id] ??= { index: 0, answers: {} };
  const saved = progress.answers.whole ??= { text: '', checks: 0 };
  const transcript = lesson.transcript || lesson.segments.map(cue => cue.text).join('\n');
  const media = lesson.kind === 'youtube'
    ? '<div class="youtube-player"><div id="whole-youtube"></div></div>'
    : '<audio id="media" controls preload="metadata" src="' + e(lesson.media) + '"></audio>';
  shell('<div class="practice-head"><div class="row between"><button class="text-btn" data-nav="library">Về thư viện</button>' +
    '<button class="icon-btn" data-action="delete-lesson" aria-label="Xóa bài này">' + icon('trash') + '</button></div>' +
    '<h1>' + e(lesson.title) + '</h1></div><section class="panel panel-pad whole-practice">' +
    '<div class="row between"><h2>Luyện cả bài</h2><button class="btn secondary" data-action="edit-timing">Đánh dấu mốc từng câu</button></div>' + media +
    '<label class="field" for="whole-answer">Lời bạn nghe được<textarea id="whole-answer" maxlength="45000" rows="9" spellcheck="false">' +
    e(saved.text) + '</textarea></label><button class="btn primary" id="whole-check">Kiểm tra</button>' +
    '<p role="status" id="whole-feedback">' + (saved.checks ? 'Lần chấm gần nhất: ' + e(saved.score) + '%' : '') + '</p>' +
    '<details><summary>Xem lời thoại</summary><p class="full-transcript">' + e(transcript) + '</p></details></section>');
  if (lesson.kind === 'youtube') embeddedMedia = online.mountYouTube($('#whole-youtube'), lesson.youtubeId);
  const input = $('#whole-answer');
  input.addEventListener('input', () => {
    saved.text = input.value;
    saved.editedAt = Date.now();
    persist();
  });
  const checkButton = $('#whole-check');
  const check = async () => {
    if (checkButton.disabled) return;
    const actual = input.value;
    const feedback = $('#whole-feedback');
    if (!tokens(actual).length) { feedback.textContent = 'Hãy nhập lời bạn nghe được.'; return; }
    if (state.settings.stopOnCheck) stop();
    checkButton.disabled = true;
    feedback.textContent = 'Đang chấm…';
    const gradedAt = Math.max(Date.now(), (saved.gradedAt || 0) + 1);
    try {
      const score = await online.scoreWhole(transcript, actual);
      if (!saved.checks) saved.firstScore = score;
      saved.text = input.value;
      saved.checkedText = actual;
      saved.score = score;
      saved.checks++;
      saved.gradedAt = gradedAt;
      saved.editedAt = Math.max(saved.editedAt || 0, gradedAt);
      today().checks++;
      persist(true);
      feedback.textContent = 'Lần chấm gần nhất: ' + score + '%';
    } catch (error) {
      feedback.textContent = error.message;
    } finally {
      checkButton.disabled = false;
    }
  };
  checkButton.addEventListener('click', check);
  input.addEventListener('keydown', event => {
    if (event.key !== 'Enter' || event.shiftKey || event.isComposing || event.repeat) return;
    event.preventDefault();
    check();
  });
}
function persist(immediate = false) {
  if (!hydrated) return;
  stateDirty = true;
  clearTimeout(saveTimer);
  if (online) {
    if (immediate) recordOnline();
    else saveTimer = setTimeout(recordOnline, 350);
    return;
  }
  saveRevision++;
  saveTimer = setTimeout(() => {
    const body = JSON.stringify(state), revision = saveRevision;
    saveQueue = saveQueue.catch(() => {}).then(() => api('/api/state', { method: 'PUT', body })).then(() => {
      if (revision === saveRevision) stateDirty = false;
    }).catch(error => toast('Chưa lưu được tiến độ: ' + error.message, true));
  }, 350);
}
const lp=(l=current)=>state.progress[l?.id]||{index:0,answers:{}};
function answer() {const p=state.progress[current.id]??={index:0,answers:{}};const a=p.answers[index]??={text:'',checks:0,hints:0,revealed:false};if(a.checkedText===undefined&&a.checks&&a.score===100&&compare(current.segments[index].text,a.text).score===100)a.checkedText=a.text;return a;}
const practiced=l=>Object.values(lp(l).answers).filter(a=>a.checks||a.revealed).length;
function stats(){const answers=Object.values(state.progress).flatMap(p=>Object.values(p.answers||{})).filter(a=>a.checks);return {count:answers.length,average:answers.length?Math.round(answers.reduce((s,a)=>s+(a.firstScore||0),0)/answers.length):0,complete:library.filter(l=>practiced(l)>=l.segments.length).length,minutes:Math.floor(Object.values(state.days).reduce((s,d)=>s+(d.seconds||0),0)/60)};}
function today(){return state.days[dayKey()]??={seconds:0,checks:0};}
