function statStrip(){const s=stats();return `<div class="stat-strip"><div class="stat-item"><div class="stat-icon">${icon('clock')}</div><div><div class="stat-value">${s.minutes}<small>phút</small></div><div class="stat-desc">Thời gian đã nghe</div></div></div><div class="stat-item"><div class="stat-icon">${icon('check')}</div><div><div class="stat-value">${s.count}<small>câu</small></div><div class="stat-desc">Đã chép và kiểm tra</div></div></div><div class="stat-item"><div class="stat-icon">${icon('target')}</div><div><div class="stat-value">${s.count?s.average:'—'}<small>${s.count?'%':''}</small></div><div class="stat-desc">Độ chính xác lần chấm đầu</div></div></div></div>`;}
function card(l){const [ic,color]=scene[l.topic]||['wave','#dce4d9'];const done=practiced(l),duration=l.duration||l.segments.at(-1).end;return `<button class="lesson-card" data-lesson="${l.id}" aria-label="Luyện ${e(l.title)}"><div class="card-art" style="--scene:${color}"><div class="art-lines"></div>${icon(ic,'scene-icon')}<span class="part-label">${l.custom?'CỦA BẠN':'TOEIC · PART '+l.part}</span><span class="art-play">${icon('play')}</span><span class="duration">${ft(duration)}</span></div><div class="card-body"><div class="topic">${e(l.topic)}</div><h3>${e(l.title)}</h3><p>${e(l.description)}</p><div class="card-foot"><span>${l.segments.length} câu &nbsp;·&nbsp; ${done?done+' đã luyện':'Chưa luyện'}</span><span class="level">${l.level==='Advanced'?'Nâng cao':'Trung cấp'}</span></div></div><div class="card-progress"><span style="width:${done/l.segments.length*100}%"></span></div></button>`;}
