function cardsHTML(home=false){const list=filterCards();return list.length?list.slice(0,home?6:1000).map(card).join(''):`<div class="empty">${icon('search')}<h3>Chưa tìm thấy bài nghe</h3><p>Thử chọn chủ đề khác hoặc thêm bài nghe của bạn.</p><button class="btn secondary" data-action="import">${icon('plus')}Thêm bài nghe</button></div>`;}
